=== src/main/java/hotel/reports/OccupancyReport.java
     1	package hotel.reports;
     2	
     3	import hotel.reservations.Reservation;
     4	import hotel.reservations.ReservationStore;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.time.LocalDate;
     8	import java.util.ArrayList;
     9	import java.util.Comparator;
    10	import java.util.List;
    11	
    12	/** Which rooms are occupied on a given night, for the front desk (CSV). */
    13	public final class OccupancyReport extends Report {
    14	
    15	    private final Rooms rooms;
    16	    private final ReservationStore store;
    17	    private LocalDate night;
    18	
    19	    public OccupancyReport(Rooms rooms, ReservationStore store) {
    20	        this.rooms = rooms;
    21	        this.store = store;
    22	    }
    23	
    24	    public String generate(LocalDate night) {
    25	        this.night = night;
    26	        return generate();
    27	    }
    28	
    29	    @Override
    30	    protected String reportName() {
    31	        return "occupancy";
    32	    }
    33	
    34	    @Override
    35	    protected String period() {
    36	        return night.toString();
    37	    }
    38	
    39	    @Override
    40	    protected String header() {
    41	        return "room,type,reservation,check_in,check_out";
    42	    }
    43	
    44	    @Override
    45	    protected String dataLines() {
    46	        List<Reservation> occupying = new ArrayList<>();
    47	        for (Reservation reservation : store.all()) {
    48	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
    49	            if (reservation.isPaid() && coversNight) {
    50	                occupying.add(reservation);
    51	            }
    52	        }
    53	        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));
    54	
    55	        StringBuilder lines = new StringBuilder();
    56	        for (Reservation reservation : occupying) {
    57	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
    58	            lines.append(room.number()).append(',')
    59	                    .append(room.type()).append(',')
    60	                    .append(reservation.id()).append(',')
    61	                    .append(reservation.checkIn()).append(',')
    62	                    .append(reservation.checkOut()).append('\n');
    63	        }
    64	        return lines.toString();
    65	    }
    66	
    67	    @Override
    68	    protected String totalLine() {
    69	        List<Reservation> occupying = new ArrayList<>();
    70	        for (Reservation reservation : store.all()) {
    71	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
    72	            if (reservation.isPaid() && coversNight) {
    73	                occupying.add(reservation);
    74	            }
    75	        }
    76	        return "total," + occupying.size() + '/' + rooms.all().size();
    77	    }
    78	}
=== src/main/java/hotel/reports/RatePlansReport.java
     1	package hotel.reports;
     2	
     3	import hotel.reservations.RatePlan;
     4	import hotel.reservations.Reservation;
     5	import hotel.reservations.ReservationStore;
     6	import java.math.BigDecimal;
     7	import java.time.YearMonth;
     8	import java.util.ArrayList;
     9	import java.util.EnumMap;
    10	import java.util.List;
    11	import java.util.Map;
    12	
    13	/** Shows which rate plan brings more money from reservations that start in a given month (CSV). */
    14	public final class RatePlansReport extends Report {
    15	
    16	    private final ReservationStore store;
    17	    private YearMonth month;
    18	
    19	    public RatePlansReport(ReservationStore store) {
    20	        this.store = store;
    21	    }
    22	
    23	    public String generate(YearMonth month) {
    24	        this.month = month;
    25	        return generate();
    26	    }
    27	
    28	    @Override
    29	    protected String reportName() {
    30	        return "rate-plans";
    31	    }
    32	
    33	    @Override
    34	    protected String period() {
    35	        return month.toString();
    36	    }
    37	
    38	    @Override
    39	    protected String header() {
    40	        return "rate_plan,reservations,amount";
    41	    }
    42	
    43	    @Override
    44	    protected String dataLines() {
    45	        Map<RatePlan, PlanStats> statsByPlan = calculateStats();
    46	
    47	        StringBuilder lines = new StringBuilder();
    48	        lines.append(RatePlan.STANDARD).append(',')
    49	                .append(statsByPlan.get(RatePlan.STANDARD).count).append(',')
    50	                .append(statsByPlan.get(RatePlan.STANDARD).revenue.toPlainString()).append('\n');
    51	        lines.append(RatePlan.NON_REFUNDABLE).append(',')
    52	                .append(statsByPlan.get(RatePlan.NON_REFUNDABLE).count).append(',')
    53	                .append(statsByPlan.get(RatePlan.NON_REFUNDABLE).revenue.toPlainString()).append('\n');
    54	        return lines.toString();
    55	    }
    56	
    57	    @Override
    58	    protected String totalLine() {
    59	        Map<RatePlan, PlanStats> statsByPlan = calculateStats();
    60	        int totalCount = 0;
    61	        BigDecimal totalRevenue = BigDecimal.ZERO.setScale(2);
    62	        for (PlanStats stats : statsByPlan.values()) {
    63	            totalCount += stats.count;
    64	            totalRevenue = totalRevenue.add(stats.revenue);
    65	        }
    66	        return "total," + totalCount + ',' + totalRevenue.toPlainString();
    67	    }
    68	
    69	    private Map<RatePlan, PlanStats> calculateStats() {
    70	        Map<RatePlan, PlanStats> statsByPlan = new EnumMap<>(RatePlan.class);
    71	        statsByPlan.put(RatePlan.STANDARD, new PlanStats());
    72	        statsByPlan.put(RatePlan.NON_REFUNDABLE, new PlanStats());
    73	
    74	        List<Reservation> withRevenue = new ArrayList<>();
    75	        for (Reservation reservation : store.all()) {
    76	            boolean keptMoney = reservation.amountKept().signum() > 0;
    77	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
    78	            if (keptMoney && startsInMonth) {
    79	                withRevenue.add(reservation);
    80	            }
    81	        }
    82	
    83	        for (Reservation reservation : withRevenue) {
    84	            PlanStats stats = statsByPlan.get(reservation.ratePlan());
    85	            stats.count++;
    86	            stats.revenue = stats.revenue.add(reservation.amountKept());
    87	        }
    88	
    89	        return statsByPlan;
    90	    }
    91	
    92	    private static class PlanStats {
    93	        int count = 0;
    94	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
    95	    }
    96	}
=== src/main/java/hotel/reports/Report.java
     1	package hotel.reports;
     2	
     3	/**
     4	 * Base for all CSV reports. Every report starts with a title line (inn name, report name, period),
     5	 * then a header, data lines, and a total line. Future changes to this format (such as adding a
     6	 * generation date) apply to all reports at once.
     7	 */
     8	public abstract class Report {
     9	
    10	    private static final String INN_NAME = "Pousada Maré Alta";
    11	
    12	    protected abstract String reportName();
    13	
    14	    protected abstract String period();
    15	
    16	    protected abstract String header();
    17	
    18	    protected abstract String dataLines();
    19	
    20	    protected abstract String totalLine();
    21	
    22	    public String generate() {
    23	        StringBuilder csv = new StringBuilder();
    24	        csv.append(INN_NAME).append(',').append(reportName()).append(',').append(period()).append('\n');
    25	        csv.append(header()).append('\n');
    26	        csv.append(dataLines());
    27	        csv.append(totalLine()).append('\n');
    28	        return csv.toString();
    29	    }
    30	}
